"""Recoverable trusted-editor HTML projection."""
import html
import json
from pathlib import Path


def render(state):
    data = json.dumps(state, ensure_ascii=True).replace('<', '\\u003c')
    script = Path(__file__).with_name('attention_editor.js').read_text(encoding='utf-8')
    return '''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'none'"><title>B关注分析 · 可信编辑</title><style>
body{font:16px/1.6 system-ui,sans-serif;color:#17212e;background:#f7f9fb;max-width:1000px;margin:2rem auto;padding:0 1rem}h1{font-size:1.8rem}h2{font-size:1.3rem;margin-top:1.6rem}section{border:1px solid #c8d0da;border-radius:8px;padding:1rem;margin:1rem 0}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#eef1f5;padding:.7rem}label{display:block;margin:.7rem 0}input,select,textarea,button{font:inherit;max-width:100%;box-sizing:border-box}select,textarea,input{width:100%;padding:.5rem}textarea{min-height:6rem}button{padding:.5rem 1rem;margin:.3rem .3rem .3rem 0;cursor:pointer}button:hover{background:#e3e8ee}button:disabled{opacity:.6;cursor:default}:focus-visible{outline:2px solid #315879;outline-offset:2px}::selection{background:#cbdff0;color:#17212e}a{color:#254e70;text-underline-offset:.2em}#message{color:#80300c;min-height:1.6rem}small{color:#3f5267}#source{user-select:text}#saved p{overflow-wrap:anywhere}@media(max-width:600px){body{margin:.5rem auto;padding:0 .6rem}section{padding:.7rem}button{white-space:normal}}
</style><h1>B关注分析</h1><p>仅供本地可信编辑。核对分析是否忠实，不表示认可B的专业判断。</p><p id="revision"></p><p id="material"></p><p>下载只生成草稿。请在本机窗口应用补丁，成功后重开本页核对。</p><section><h2>原话与原分</h2><label>评语记录<select id="record"></select></label><label>普通分区<select id="section"></select></label><p id="locator"></p><pre id="source" tabindex="0"></pre><div id="scores"></div></section><section><h2>创建或纠正一项解释</h2><label>解释项<select id="opinion"></select></label><p>在上方原话中选中文字后，点击“采用选中文字”；键盘也可用下方原话片段选择。</p><button id="capture" type="button">采用选中文字</button><label>原话片段<select id="passage"></select></label><p id="evidence"></p><label>分析解释<textarea id="interpretation"></textarea></label><label>核对状态<select id="status"><option value="working">工作解释</option><option value="needs_review">待核对</option><option value="confirmed">已核对分析</option><option value="withdrawn">撤回</option></select></label><label>修改者声明<input id="actor" autocomplete="off"></label><label>修改理由<input id="reason" autocomplete="off"></label><button id="stage" type="button">加入草稿</button><button id="download" type="button" disabled>下载草稿补丁</button><p id="draft" role="status">没有未应用草稿</p><p id="message" role="alert"></p></section><section><h2>已保存解释</h2><div id="saved"></div></section><section><h2>A工作参照</h2><p id="a-version"></p><div id="a-items"></div></section><section><h2>保存历史</h2><div id="history"></div></section><script id="attention-data" type="application/json">''' + data + '</script><script>' + script + '</script></html>'
